class Solution {
public:
    vector<int> findMaximums(vector<int>& nums) {
        int n = nums.size();
        vector<int> left(n), right(n), stack;
        for (int i = 0; i < n; ++i) {
            while (!stack.empty() && nums[stack.back()] >= nums[i]) {
                stack.pop_back();
            }
            left[i] = stack.empty() ? -1 : stack.back();
            stack.push_back(i);
        }
        stack.clear();
        for (int i = n - 1; i >= 0; --i) {
            while (!stack.empty() && nums[stack.back()] >= nums[i]) {
                stack.pop_back();
            }
            right[i] = stack.empty() ? n : stack.back();
            stack.push_back(i);
        }
        vector<int> answer(n, INT_MIN);
        for (int i = 0; i < n; ++i) {
            int length = right[i] - left[i] - 1;
            answer[length - 1] = max(answer[length - 1], nums[i]);
        }
        for (int i = n - 2; i >= 0; --i) {
            answer[i] = max(answer[i], answer[i + 1]);
        }
        return answer;
    }
};
